type Read<T> =
  | { ok: true; value: T }
  | { ok: false; reason: "refused" | "truncated" | "invalid"; detail: string };

// Claude Messages: inspect stop_reason before touching the text block.
function readClaude(msg: { stop_reason: string | null; content: { type: string; text?: string }[] }): Read<unknown> {
  if (msg.stop_reason === "refusal") return { ok: false, reason: "refused", detail: "stop_reason refusal" };
  if (msg.stop_reason === "max_tokens") return { ok: false, reason: "truncated", detail: "raise max_tokens and retry" };
  const text = msg.content.find((b) => b.type === "text")?.text ?? "";
  return validate(JSON.parse(text));
}

// OpenAI Responses: an incomplete status or a refusal item is not schema output.
function readResponses(r: { status: string; incomplete_details?: { reason?: string }; output: any[] }): Read<unknown> {
  if (r.status === "incomplete") return { ok: false, reason: "truncated", detail: r.incomplete_details?.reason ?? "unknown" };
  const part = r.output.find((i) => i.type === "message")?.content?.[0];
  if (part?.type === "refusal") return { ok: false, reason: "refused", detail: part.refusal };
  return validate(JSON.parse(part?.text ?? ""));
}

